33\u0438\u043d\u0430\u043b\u0443. \u0412\u0410\u0420\u0418\u0410\u0426\u0418\u0418 \u0421\u041e\u0412\u041f\u0410\u0414\u0410\u042e\u0422 (\u0438\u0441\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u043e: \u0432 \u043f\u0440\u043e\u0448\u043b\u043e\u0439 \u0442\u0430\u0431\u043b\u0438\u0446\u0435 CP 'Z z \u0451 \u0435' \u0431\u044b\u043b \u043e\u0448\u0438\u0431\u043e\u0447\u0435\u043d)\n9  | 10 2 1                      | 1 10 2                | 1 10 2 (=)            | \u0427\u0438\u0441\u043b\u0430 \u043a\u0430\u043a \u0441\u0442\u0440\u043e\u043a\u0438, \u043b\u0435\u043a\u0441\u0438\u043a\u043e\u0433\u0440\u0430\u0444\u0438\u0447\u0435\u0441\u043a\u0438 ('1'<'2', '10' \u043f\u043e\u0441\u043b\u0435 '1' \u043f\u043e \u043f\u0440\u0435\u0444\u0438\u043a\u0441\u0443)\n10 | Apple                       | Apple                 | Apple (=)             | \u041e\u0434\u0438\u043d\u043e\u0447\u043d\u044b\u0439 \u044d\u043b\u0435\u043c\u0435\u043d\u0442\n11 | apple Banana Cherry (\u041d\u041e\u0412\u042b\u0419) | Banana Cherry apple   | apple Banana Cherry   | \u0420\u0410\u0421\u0425\u041e\u0416\u0414\u0415\u041d\u0418\u0415 \u2014 \u0433\u043b\u0430\u0432\u043d\u044b\u0439 \u0440\u0430\u0437\u043b\u0438\u0447\u0430\u044e\u0449\u0438\u0439 \u043a\u0435\u0439\u0441 (\u0437\u0430\u043c\u0435\u043d\u0430 \u043f\u0440\u0435\u0436\u043d\u0435\u0439 \u0440\u043e\u043b\u0438 \u21161). \u0412\u042b\u0412\u0415\u0420\u0415\u041d\u041e \u043f\u043e P1: CP: 'B'(66)<'C'(67)<'a'(97) \u2192 \u0437\u0430\u0433\u043b\u0430\u0432\u043d\u044b\u0435 Banana, Cherry \u0432\u043f\u0435\u0440\u0435\u0434\u0438 \u0441\u0442\u0440\u043e\u0447\u043d\u043e\u0433\u043e apple; CF: \u043a\u043b\u044e\u0447\u0438 'apple'<'banana'<'cherry' \u2192 'apple Banana Cherry'\n\n\u0421\u0412\u041e\u0414\u041a\u0410 \u0420\u0410\u0421\u0425\u041e\u0416\u0414\u0415\u041d\u0418\u0419 CP vs CF: \u043a\u0435\u0439\u0441\u044b 7 \u0438 11. \u0412\u0441\u0435 \u043e\u0441\u0442\u0430\u043b\u044c\u043d\u044b\u0435 (1\u20136, 8\u201310) \u2014 \u0441\u043e\u0432\u043f\u0430\u0434\u0430\u044e\u0449\u0438\u0435. \u041a\u0430\u0436\u0434\u043e\u0435 \u0440\u0430\u0441\u0445\u043e\u0436\u0434\u0435\u043d\u0438\u0435 \u0432\u044b\u0432\u0435\u0440\u0435\u043d\u043e \u043f\u043e\u0441\u0438\u043c\u0432\u043e\u043b\u044c\u043d\u043e \u043f\u043e \u043a\u043e\u0434\u043f\u043e\u0438\u043d\u0442\u0430\u043c (\u043f\u0440\u043e\u0446\u0435\u0434\u0443\u0440\u0430 P1, \u0441\u043c. \u00a73 \u0448\u0430\u0433 0).\n\n\u2550\u2550\u2550 3. \u041f\u0420\u041e\u0426\u0415\u0414\u0423\u0420\u0410 \u0412\u0410\u041b\u0418\u0414\u0410\u0426\u0418\u0418 (design) \u2550\u2550\u2550\n\n\u0428\u0430\u0433 0 (P1, \u0432\u044b\u043f\u043e\u043b\u043d\u044f\u0435\u0442\u0441\u044f \u0414\u041e \u0444\u0438\u043a\u0441\u0430\u0446\u0438\u0438 \u044d\u0442\u0430\u043b\u043e\u043d\u043e\u0432): \u0434\u043b\u044f \u043a\u0430\u0436\u0434\u043e\u0433\u043e \u0440\u0430\u0441\u0445\u043e\u0434\u044f\u0449\u0435\u0433\u043e\u0441\u044f \u043a\u0435\u0439\u0441\u0430 \u2014 \u043f\u043e\u0441\u0438\u043c\u0432\u043e\u043b\u044c\u043d\u0430\u044f \u0432\u044b\u0432\u0435\u0440\u043a\u0430 \u043f\u043e \u043a\u043e\u0434\u043f\u043e\u0438\u043d\u0442\u0430\u043c: \u0441\u043f\u0438\u0441\u043e\u043a \u0441\u043b\u043e\u0432, \u0438\u0445 ord() \u043f\u043e \u043f\u043e\u0437\u0438\u0446\u0438\u044f\u043c, \u043f\u043e\u0440\u044f\u0434\u043e\u043a \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u044f; \u0432 CF \u2014 \u0432\u044b\u0447\u0438\u0441\u043b\u0435\u043d\u0438\u0435 casefold-\u043a\u043b\u044e\u0447\u0435\u0439 \u0438 \u0440\u0430\u0437\u0440\u0435\u0448\u0435\u043d\u0438\u0435 ties \u043f\u043e \u043e\u0440\u0438\u0433\u0438\u043d\u0430\u043b\u0443. \u0421\u0442\u0430\u0442\u0443\u0441: \u0412\u042b\u041f\u041e\u041b\u041d\u0415\u041d\u0410 \u0434\u043b\u044f \u043a\u0435\u0439\u0441\u043e\u0432 1, 6, 7, 8, 11 (\u0432\u043a\u043b\u044e\u0447\u0430\u044f \u0438\u0441\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u0435 \u21161 \u043f\u043e \u0437\u0430\u043c\u0435\u0447\u0430\u043d\u0438\u044e \u0438\u0441\u0441\u043b\u0435\u0434\u043e\u0432\u0430\u0442\u0435\u043b\u044f \u0438 \u043e\u0431\u043d\u0430\u0440\u0443\u0436\u0435\u043d\u0438\u0435 \u0441\u043e\u0432\u043f\u0430\u0434\u0435\u043d\u0438\u044f \u0432 \u21168). \u0421\u043e\u0432\u043f\u0430\u0434\u0430\u044e\u0449\u0438\u0435 \u043a\u0435\u0439\u0441\u044b \u043f\u0440\u043e\u0432\u0435\u0440\u0435\u043d\u044b \u043d\u0430 \u0438\u0434\u0435\u043d\u0442\u0438\u0447\u043d\u043e\u0441\u0442\u044c \u043f\u043e\u0440\u044f\u0434\u043a\u043e\u0432 \u043e\u0431\u043e\u0438\u0445 \u043a\u043b\u044e\u0447\u0435\u0439.\n\u0428\u0430\u0433 1. \u042d\u0442\u0430\u043b\u043e\u043d\u044b \u0444\u0438\u043a\u0441\u0438\u0440\u0443\u044e\u0442\u0441\u044f \u043a\u0430\u043a \u0444\u0430\u0439\u043b \u043e\u0436\u0438\u0434\u0430\u043d\u0438\u0439: (\u0432\u0445\u043e\u0434, \u043a\u0430\u043d\u0430\u043b, \u043e\u0436\u0438\u0434\u0430\u0435\u043c\u044b\u0439 stdout \u0434\u043b\u044f CP, \u043e\u0436\u0438\u0434\u0430\u0435\u043c\u044b\u0439 \u0434\u043b\u044f CF). \u0420\u0430\u0441\u0445\u043e\u0434\u044f\u0449\u0438\u0435\u0441\u044f \u043a\u0435\u0439\u0441\u044b: 7, 11; \u0441\u043e\u0432\u043f\u0430\u0434\u0430\u044e\u0449\u0438\u0435: 1\u20136, 8\u201310.\n\u0428\u0430\u0433 2. \u041f\u0440\u043e\u0433\u043e\u043d (\u0431\u0443\u0434\u0443\u0449\u0438\u0439, \u043f\u0440\u0438 \u043f\u0435\u0440\u0435\u0445\u043e\u0434\u0435 \u043a \u0438\u0441\u043f\u043e\u043b\u043d\u0435\u043d\u0438\u044e): \u0440\u0435\u0448\u0435\u043d\u0438\u0435 \u0437\u0430\u043f\u0443\u0441\u043a\u0430\u0435\u0442\u0441\u044f \u043d\u0430 \u043a\u0430\u0436\u0434\u044b\u0439 \u043a\u0435\u0439\u0441 \u0432 \u043e\u0431\u043e\u0438\u0445 \u043a\u0430\u043d\u0430\u043b\u0430\u0445 (argv \u0438 stdin), \u043c\u0438\u043d\u0438\u043c\u0443\u043c \u043d\u0430 \u043a\u0435\u0439\u0441\u0430\u0445 1, 3, 9, 11 \u2014 \u0434\u043b\u044f \u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0435\u043d\u0438\u044f \u044d\u043a\u0432\u0438\u0432\u0430\u043b\u0435\u043d\u0442\u043d\u043e\u0441\u0442\u0438 \u043a\u0430\u043d\u0430\u043b\u043e\u0432.\n\u0428\u0430\u0433 3. \u0421\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0435: byte-accurate diff stdout (\u0441 \u0443\u0447\u0451\u0442\u043e\u043c \u0437\u0430\u0432\u0435\u0440\u0448\u0430\u044e\u0449\u0435\u0433\u043e '\\n') + \u043a\u043e\u0434 \u0432\u044b\u0445\u043e\u0434\u0430 0 + \u043f\u0443\u0441\u0442\u043e\u0439 stderr. \u041b\u044e\u0431\u043e\u0435 \u0431\u0430\u0439\u0442\u043e\u0432\u043e\u0435 \u0440\u0430\u0441\u0445\u043e\u0436\u0434\u0435\u043d\u0438\u0435 \u2014 \u043d\u0435\u0441\u043e\u043e\u0442\u0432\u0435\u0442\u0441\u0442\u0432\u0438\u0435, \u0431\u0435\u0437 \u043d\u043e\u0440\u043c\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u0438 \u043f\u0440\u043e\u0431\u0435\u043b\u043e\u0432.\n\u0428\u0430\u0433 4. \u041e\u0442\u0447\u0451\u0442: \u0442\u0430\u0431\u043b\u0438\u0446\u0430 \u00ab\u043a\u0435\u0439\u0441 \u00d7 \u0432\u0430\u0440\u0438\u0430\u043d\u0442 \u00d7 \u043a\u0430\u043d\u0430\u043b \u2192 PASS/FAIL\u00bb; \u0434\u043b\u044f FAIL \u2014 hex-dump \u0444\u0430\u043a\u0442\u0438\u0447\u0435\u0441\u043a\u043e\u0433\u043e \u0438 \u043e\u0436\u0438\u0434\u0430\u0435\u043c\u043e\u0433\u043e.\n\u041a\u0440\u0438\u0442\u0435\u0440\u0438\u0439 \u0443\u0441\u043f\u0435\u0445\u0430: 100% byte-accurate \u043f\u0440\u043e\u0445\u043e\u0436\u0434\u0435\u043d\u0438\u0435 CP \u043f\u043e \u0432\u0441\u0435\u043c \u043a\u0435\u0439\u0441\u0430\u043c \u0438 \u043e\u0431\u043e\u0438\u043c \u043a\u0430\u043d\u0430\u043b\u0430\u043c; CF \u2014 \u043e\u0442\u0447\u0451\u0442\u043d\u0430\u044f \u0432\u0430\u0440\u0438\u0430\u0446\u0438\u044f (\u0447\u0443\u0432\u0441\u0442\u0432\u0438\u0442\u0435\u043b\u044c\u043d\u043e\u0441\u0442\u044c \u043a U1), \u043d\u0435 \u043a\u0440\u0438\u0442\u0435\u0440\u0438\u0439 PASS/FAIL.\n\n\u2550\u2550\u2550 4. \u041a\u041e\u041d\u0422\u0420\u041e\u041b\u0418 (\u0431\u0435\u0437 \u0438\u0437\u043c\u0435\u043d\u0435\u043d\u0438\u0439) \u2550\u2550\u2550\n\nC1. \u0414\u0435\u0442\u0435\u0440\u043c\u0438\u043d\u0438\u0437\u043c: \u0434\u0432\u0430 \u043f\u0440\u043e\u0433\u043e\u043d\u0430 \u043d\u0430 \u043e\u0434\u043d\u043e\u043c \u0432\u0445\u043e\u0434\u0435 \u2014 \u0431\u0430\u0439\u0442-\u0432-\u0431\u0430\u0439\u0442 \u043e\u0434\u0438\u043d\u0430\u043a\u043e\u0432\u044b\u0439 \u0432\u044b\u0432\u043e\u0434.\nC2. \u041f\u0443\u0441\u0442\u043e\u0439 \u0432\u0445\u043e\u0434: '' \u0438 '   ' \u2192 stdout \u0441\u043e\u0434\u0435\u0440\u0436\u0438\u0442 \u0442\u043e\u043b\u044c\u043a\u043e '\\n', \u043a\u043e\u0434 0, \u0431\u0435\u0437 traceback.\nC3. \u0421\u0442\u0430\u0431\u0438\u043b\u044c\u043d\u043e\u0441\u0442\u044c: \u043a\u0435\u0439\u0441 5 \u2014 \u0441\u043e\u0445\u0440\u0430\u043d\u0435\u043d\u0438\u0435 \u0438\u0441\u0445\u043e\u0434\u043d\u043e\u0433\u043e \u043f\u043e\u0440\u044f\u0434\u043a\u0430 \u0440\u0430\u0432\u043d\u044b\u0445 CF-\u043a\u043b\u044e\u0447\u0435\u0439; \u0434\u043b\u044f CP \u0440\u0430\u0432\u043d\u044b\u0435 \u0441\u0442\u0440\u043e\u043a\u0438 \u043d\u0435\u043e\u0442\u043b\u0438\u0447\u0438\u043c\u044b (\u043e\u0442\u043c\u0435\u0447\u0435\u043d\u043e \u0434\u043b\u044f \u043f\u043e\u043b\u043d\u043e\u0442\u044b).\nC4. \u042d\u043a\u0432\u0438\u0432\u0430\u043b\u0435\u043d\u0442\u043d\u043e\u0441\u0442\u044c \u043a\u0430\u043d\u0430\u043b\u043e\u0432: argv \u0438 stdin \u0434\u0430\u044e\u0442 \u0438\u0434\u0435\u043d\u0442\u0438\u0447\u043d\u044b\u0439 \u0432\u044b\u0432\u043e\u0434.\nC5. \u041e\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0438\u0435 \u0441\u043a\u0440\u044b\u0442\u043e\u0439 \u043d\u043e\u0440\u043c\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u0438: \u0431\u0435\u0437 \u0434\u0435\u0434\u0443\u043f\u043b\u0438\u043a\u0430\u0446\u0438\u0438 (4), \u0431\u0435\u0437 \u0447\u0438\u0441\u043b\u043e\u0432\u043e\u0439 \u0441\u043e\u0440\u0442\u0438\u0440\u043e\u0432\u043a\u0438 (7, 9), \u043f\u0443\u043d\u043a\u0442\u0443\u0430\u0446\u0438\u044f \u043d\u0435 \u043e\u0442\u0440\u0435\u0437\u0430\u0435\u0442\u0441\u044f (6).\nC6. \u0427\u0435\u0441\u0442\u043d\u043e\u0441\u0442\u044c design-only: \u0432 \u043e\u0442\u0447\u0451\u0442\u0435 \u044f\u0432\u043d\u043e \u0443\u043a\u0430\u0437\u0430\u043d\u043e, \u0447\u0442\u043e \u044d\u043a\u0441\u043f\u0435\u0440\u0438\u043c\u0435\u043d\u0442 \u043d\u0435 \u0432\u044b\u043f\u043e\u043b\u043d\u044f\u043b\u0441\u044f; \u044d\u0442\u0430\u043b\u043e\u043d\u044b \u0432\u044b\u0432\u0435\u0434\u0435\u043d\u044b \u0430\u043d\u0430\u043b\u0438\u0442\u0438\u0447\u0435\u0441\u043a\u0438 (\u0438 \u0432\u044b\u0432\u0435\u0440\u0435\u043d\u044b \u043f\u043e P1), \u043d\u0435 \u043f\u043e\u043b\u0443\u0447\u0435\u043d\u044b \u043f\u0440\u043e\u0433\u043e\u043d\u043e\u043c \u0440\u0435\u0448\u0435\u043d\u0438\u044f.\n\n\u2550\u2550\u2550 5. \u0420\u0418\u0421\u041a\u0418 \u0418 \u0420\u0415\u0410\u041b\u0418\u0417\u0423\u0415\u041c\u041e\u0421\u0422\u042c \u2550\u2550\u2550\n\nR1 (\u043e\u0431\u043d\u043e\u0432\u043b\u0451\u043d): \u0438\u043d\u0442\u0435\u0440\u043f\u0440\u0435\u0442\u0430\u0446\u0438\u044f \u00abalphabetically\u00bb (U1) \u043c\u0435\u043d\u044f\u0435\u0442 \u043f\u043e\u0440\u044f\u0434\u043e\u043a \u043d\u0430 \u043a\u0435\u0439\u0441\u0430\u0445 7 \u0438 11 (\u0431\u043e\u043b\u044c\u0448\u0435 \u041d\u0415 \u043d\u0430 \u043a\u0435\u0439\u0441\u0435 1 \u2014 \u0442\u0430\u043c \u043e\u0431\u0430 \u0432\u0430\u0440\u0438\u0430\u043d\u0442\u0430 \u0441\u043e\u0432\u043f\u0430\u0434\u0430\u044e\u0442). \u0420\u0435\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u044f \u0441 casefold/lower \u0438\u043b\u0438 locale \u043f\u0440\u043e\u0439\u0434\u0451\u0442 \u0441\u043e\u0432\u043f\u0430\u0434\u0430\u044e\u0449\u0438\u0435 \u043a\u0435\u0439\u0441\u044b, \u043d\u043e \u0440\u0430\u0437\u043e\u0439\u0434\u0451\u0442\u0441\u044f \u0441 \u0431\u0430\u0437\u043e\u0432\u044b\u043c \u043a\u043e\u043d\u0442\u0440\u0430\u043a\u0442\u043e\u043c \u0438\u043c\u0435\u043d\u043d\u043e \u043d\u0430 7 \u0438 11 \u2014 \u044d\u0442\u0438 \u0434\u0432\u0430 \u043a\u0435\u0439\u0441\u0430 \u0442\u0435\u043f\u0435\u0440\u044c \u0435\u0434\u0438\u043d\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0439 \u0434\u0438\u0441\u043a\u0440\u0438\u043c\u0438\u043d\u0430\u0442\u043e\u0440, \u0438 \u0438\u0445 \u044d\u0442\u0430\u043b\u043e\u043d\u044b \u0432\u044b\u0432\u0435\u0440\u0435\u043d\u044b \u0441 \u0434\u0432\u043e\u0439\u043d\u044b\u043c \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u0435\u043c (P1 \u0438\u0441\u0441\u043b\u0435\u0434\u043e\u0432\u0430\u0442\u0435\u043b\u044f + \u043d\u0435\u0437\u0430\u0432\u0438\u0441\u0438\u043c\u0430\u044f \u0432\u044b\u0432\u0435\u0440\u043a\u0430).\nR2. NFC vs NFD \u043c\u0435\u043d\u044f\u0435\u0442 \u043f\u043e\u0440\u044f\u0434\u043e\u043a \u0441\u043b\u043e\u0432 \u0441 \u0434\u0438\u0430\u043a\u0440\u0438\u0442\u0438\u043a\u043e\u0439; \u043a\u043e\u043d\u0442\u0440\u0430\u043a\u0442 \u2014 \u00ab\u043a\u0430\u043a \u0435\u0441\u0442\u044c, \u0431\u0435\u0437 \u043d\u043e\u0440\u043c\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u0438\u00bb; \u0432 \u044d\u0442\u0430\u043b\u043e\u043d\u043d\u044b\u0445 \u043a\u0435\u0439\u0441\u0430\u0445 \u043e\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0443\u0435\u0442.\nR3. argv-\u0442\u043e\u043a\u0435\u043d\u0438\u0437\u0430\u0446\u0438\u044f \u0432\u044b\u043f\u043e\u043b\u043d\u044f\u0435\u0442\u0441\u044f shell'\u043e\u043c \u0434\u043e \u043f\u0440\u043e\u0433\u0440\u0430\u043c\u043c\u044b; \u0441\u043b\u043e\u0432\u0430 \u0441 \u0432\u043d\u0443\u0442\u0440\u0435\u043d\u043d\u0438\u043c\u0438 \u043f\u0440\u043e\u0431\u0435\u043b\u0430\u043c\u0438 \u0432 argv \u0432\u043d\u0435 \u0431\u0430\u0437\u043e\u0432\u043e\u0433\u043e \u0441\u0446\u0435\u043d\u0430\u0440\u0438\u044f, \u0442\u0435\u0441\u0442\u044b \u043d\u0430 \u044d\u0442\u043e \u043d\u0435 \u0432\u043a\u043b\u044e\u0447\u0430\u044e\u0442\u0441\u044f.\nR4. \u0417\u0430\u0432\u0435\u0440\u0448\u0430\u044e\u0449\u0438\u0439 '\\n' \u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d (print); byte-accurate diff \u0441\u0442\u0440\u043e\u0433.\nR5. \u0422\u043e\u043a\u0435\u043d\u0438\u0437\u0430\u0446\u0438\u044f \u043d\u0435-ASCII: str.split() \u0434\u0435\u043b\u0438\u0442 \u043f\u043e Unicode-whitespace; \u0440\u0438\u0441\u043a \u043d\u0438\u0437\u043a\u0438\u0439 (\u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0435\u043d\u043e \u043f\u043e\u0432\u0435\u0434\u0435\u043d\u0438\u0435\u043c \u043d\u0430 \u043a\u0435\u0439\u0441\u0435 8 \u043f\u0440\u0438 \u0432\u044b\u0432\u0435\u0440\u043a\u0435).\n\u0420\u0435\u0430\u043b\u0438\u0437\u0443\u0435\u043c\u043e\u0441\u0442\u044c: \u0412\u042b\u0421\u041e\u041a\u0410\u042f. O(N log N \u00d7 L), \u0431\u0435\u0437 \u0441\u0435\u0442\u0438/GPU/\u0437\u0430\u0432\u0438\u0441\u0438\u043c\u043e\u0441\u0442\u0435\u0439 (\u0441\u0438\u0441\u0442\u0435\u043c\u043d\u044b\u0439 Python 3.14.4), \u0434\u0435\u0442\u0435\u0440\u043c\u0438\u043d\u0438\u0440\u043e\u0432\u0430\u043d\u043e; \u0431\u044e\u0434\u0436\u0435\u0442\u044b (60 \u0448\u0430\u0433\u043e\u0432, 224 CPU, bubblewrap) \u043f\u043e\u043a\u0440\u044b\u0432\u0430\u044e\u0442 \u0440\u0435\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u044e + \u043f\u0440\u043e\u0433\u043e\u043d 11 \u043a\u0435\u0439\u0441\u043e\u0432 \u00d7 2 \u043a\u0430\u043d\u0430\u043b\u0430 \u00d7 2 \u0432\u0430\u0440\u0438\u0430\u0446\u0438\u0438 \u0441 \u0437\u0430\u043f\u0430\u0441\u043e\u043c \u043f\u0440\u0438 \u0431\u0443\u0434\u0443\u0449\u0435\u043c \u043f\u0435\u0440\u0435\u0445\u043e\u0434\u0435 \u043a \u0438\u0441\u043f\u043e\u043b\u043d\u0435\u043d\u0438\u044e.\n\n\u0417\u0410\u042f\u0412\u041b\u0415\u041d\u0418\u0415 \u041e \u0427\u0415\u0421\u0422\u041d\u041e\u0421\u0422\u0418: \u044d\u043a\u0441\u043f\u0435\u0440\u0438\u043c\u0435\u043d\u0442 \u0